# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::Handoff::ServiceStore do
  include_context "timekeeping entry writes without transactional fixtures"

  def partial_failure_entry_row(id, company_id)
    at = Time.utc(2026, 3, 1, 12)
    { "id" => id, "company_id" => company_id, "version" => 2, "project_id" => 11, "user_id" => 12, "agent_id" => nil,
      "work_date" => Date.new(2026, 3, 2), "duration" => 90.0, "note" => "Loaded", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => at, "updated_at" => at }
  end

  def partial_failure_reservation_row(entry_id, company_id, invoice_id)
    { "company_id" => company_id, "entry_id" => entry_id, "invoice_id" => invoice_id, "state" => "committed",
      "disposition" => "active", "operation_id" => SecureRandom.uuid, "created_at" => Time.utc(2026, 3, 1, 12),
      "invoice_operation_id" => nil }
  end

  # "Load: "replaces the incoming owner's tables in one transaction", so loading
  # the same checkpoint twice gives equal counts and checksums."
  # Two committed reservations for one entry break a unique index only after the
  # entries were deleted and re-inserted, so a load that is not one transaction
  # would leave the stored entry gone.
  it "rolls the whole load back when an insert fails after entries were already replaced" do
    kept = Entry.create!(company_id: 7, user_id: 1, project_id: 2, work_date: "2026-03-02", duration: 30.0,
                         note: "Kept", bill_status: "unbilled", source: "manual", source_metadata: {})
    AuditEvent.create!(company_id: 7, entry_id: kept.id, actor_type: "user", actor_id: 1, action: "create",
                       after: { "note" => "Kept" }, entry_created_at: kept.created_at, created_at: Time.current)
    Timekeeping::Admission.fence!
    checkpoint = Timekeeping::Handoff::Checkpoint.build(tables: {
      "entries" => [partial_failure_entry_row(500, 8)],
      "reservations" => [partial_failure_reservation_row(500, 8, 41), partial_failure_reservation_row(500, 8, 42)],
      "invoice_operations" => [], "entry_audits" => [], "idempotency_records" => []
    })

    store = described_class.new(connection: ApplicationRecord.connection)

    expect { store.load_checkpoint(checkpoint) }.to raise_error(Timekeeping::Handoff::Store::Error)
    expect(Entry.pluck(:id, :company_id, :note)).to eq([[kept.id, 7, "Kept"]])
    expect(AuditEvent.where(entry_id: kept.id).count).to eq(1)
    expect(Reservation.count).to eq(0)
  end
end
